#include <stdio.h>

int add(int a, int b) { return a + b; }
int sub(int a, int b) { return a - b; }
int mul(int a, int b) { return a * b; }

int main() {
    char symbols[] = {'+', '-', '*'};
    int (*functions[])(int, int) = {add, sub, mul};
    for (int i = 0; i < 3; i++) {
        printf("9 %c 3 = %d\n", symbols[i], functions[i](9, 3));
    }
    return 0;
}
